  at_history_days: {"en":"{a} of the last {n} recorded days absent","hi":"पिछले {n} दर्ज दिनों में से {a} दिन अनुपस्थित","kn":"ಕಳೆದ {n} ದಾಖಲಿತ ದಿನಗಳಲ್ಲಿ {a} ದಿನ ಗೈರು","mr":"मागील {n} नोंदवलेल्या दिवसांपैकी {a} दिवस गैरहजर"},
  at_noclass: {"en":"No class assigned yet.","hi":"अभी कोई कक्षा नहीं सौंपी गई।","kn":"ಇನ್ನೂ ಯಾವ ತರಗತಿಯನ್ನೂ ನಿಯೋಜಿಸಿಲ್ಲ.","mr":"अद्याप कोणतीही वर्गवारी (class) दिली नाही."},

