  // ---- roster --------------------------------------------------------------
  nav_roster: {"en":"Roster","hi":"नामावली","kn":"ಪಟ್ಟಿ","mr":"विद्यार्थ्यांची यादी"},
  ro_title: {"en":"Your class roster","hi":"आपकी कक्षा की नामावली","kn":"ನಿಮ್ಮ ತರಗತಿಯ ಪಟ್ಟಿ","mr":"आपल्या वर्गातील विद्यार्थ्यांची यादी"},
  ro_sub: {"en":"The children enrolled in your class. Add them one by one, or bring the whole list in from a sheet.","hi":"आपकी कक्षा में दर्ज बच्चे। एक-एक करके जोड़िए, या पूरी सूची शीट से लाइए।","kn":"ನಿಮ್ಮ ತರಗತಿಯಲ್ಲಿ ದಾಖಲಾದ ಮಕ್ಕಳು. ಒಬ್ಬೊಬ್ಬರಾಗಿ ಸೇರಿಸಿ, ಅಥವಾ ಪೂರ್ಣ ಪಟ್ಟಿಯನ್ನು ಶೀಟ್‌ನಿಂದ ತನ್ನಿ.","mr":"आपल्या वर्गात दाखल झालेली मुले. त्यांना एक-एक करून जोडा, किंवा संपूर्ण यादी एका शीटमधून आणा."},
  ro_empty: {"en":"No children yet. Add your first student to begin noticing.","hi":"अभी कोई बच्चा नहीं। टिप्पणी शुरू करने के लिए पहला छात्र जोड़िए।","kn":"ಇನ್ನೂ ಮಕ್ಕಳಿಲ್ಲ. ಟಿಪ್ಪಣಿ ಆರಂಭಿಸಲು ಮೊದಲ ವಿದ್ಯಾರ್ಥಿಯನ್ನು ಸೇರಿಸಿ.","mr":"अजून एकही विद्यार्थी नाही. नोंदी सुरू करण्यासाठी आपला पहिला विद्यार्थी जोडा."},
  ro_add: {"en":"Add a student","hi":"छात्र जोड़ें","kn":"ವಿದ್ಯಾರ್ಥಿ ಸೇರಿಸಿ","mr":"विद्यार्थी जोडा"},
  ro_name: {"en":"Full name","hi":"पूरा नाम","kn":"ಪೂರ್ಣ ಹೆಸರು","mr":"पूर्ण नाव"},
