  csv_skipped: {"en":"{n} will be skipped","hi":"{n} छोड़ दिए जाएँगे","kn":"{n} ಬಿಟ್ಟುಬಿಡಲಾಗುವುದು","mr":"{n} वगळले जातील"},
  csv_import: {"en":"Add these children","hi":"इन बच्चों को जोड़ें","kn":"ಈ ಮಕ್ಕಳನ್ನು ಸೇರಿಸಿ","mr":"या मुलांना जोडा"},
  csv_importing: {"en":"Adding…","hi":"जोड़ा जा रहा है…","kn":"ಸೇರಿಸಲಾಗುತ್ತಿದೆ…","mr":"जोडत आहे…"},
  csv_done: {"en":"{n} children added to your class.","hi":"{n} बच्चे आपकी कक्षा में जोड़े गए।","kn":"{n} ಮಕ್ಕಳನ್ನು ನಿಮ್ಮ ತರಗತಿಗೆ ಸೇರಿಸಲಾಗಿದೆ.","mr":"तुमच्या वर्गात {n} मुले जोडली गेली आहेत."},
  csv_fail: {"en":"The list could not be saved. Nothing was added.","hi":"सूची सहेजी नहीं जा सकी। कुछ भी नहीं जोड़ा गया।","kn":"ಪಟ್ಟಿ ಉಳಿಸಲಾಗಲಿಲ್ಲ. ಏನನ್ನೂ ಸೇರಿಸಿಲ್ಲ.","mr":"यादी सेव्ह झाली नाही. काहीही जोडले गेले नाही."},
  csv_emptyfile: {"en":"That file had no rows we could read.","hi":"उस फ़ाइल में पढ़ने योग्य कोई पंक्ति नहीं थी।","kn":"ಆ ಕಡತದಲ್ಲಿ ಓದಬಹುದಾದ ಸಾಲುಗಳಿಲ್ಲ.","mr":"त्या फाईलमध्ये वाचण्यासारख्या ओळी नव्हत्या."},
  csv_e_name: {"en":"Name is missing","hi":"नाम नहीं है","kn":"ಹೆಸರು ಇಲ್ಲ","mr":"नाव दिलेले नाही"},
  csv_e_roll: {"en":"Roll number must be a whole number","hi":"रोल नंबर पूर्ण संख्या होनी चाहिए","kn":"ರೋಲ್ ಸಂಖ್ಯೆ ಪೂರ್ಣ ಸಂಖ್ಯೆಯಾಗಿರಬೇಕು","mr":"रोल नंबर पूर्ण संख्या असावा"},
  csv_e_duproll: {"en":"Repeated roll number in this file","hi":"इस फ़ाइल में रोल नंबर दोहराया गया","kn":"ಈ ಕಡತದಲ್ಲಿ ರೋಲ್ ಸಂಖ್ಯೆ ಪುನರಾವರ್ತನೆ","mr":"या फाईलमध्ये रोल नंबरची पुनरावृत्ती झाली आहे"},
  csv_e_exists: {"en":"A child with this roll number is already in the class","hi":"इस रोल नंबर का बच्चा पहले से कक्षा में है","kn":"ಈ ರೋಲ್ ಸಂಖ್ಯೆಯ ಮಗು ಈಗಾಗಲೇ ತರಗತಿಯಲ್ಲಿದೆ","mr":"या रोल नंबरचे मूल आधीच वर्गात आहे"},
  csv_e_dupname: {"en":"Repeated name in this file","hi":"इस फ़ाइल में नाम दोहराया गया","kn":"ಈ ಕಡತದಲ್ಲಿ ಹೆಸರು ಪುನರಾವರ್ತನೆ","mr":"या फाईलमध्ये नावांची पुनरावृत्ती झाली आहे"},
  csv_e_class: {"en":"Grade or section is missing","hi":"कक्षा या सेक्शन नहीं है","kn":"ತರಗತಿ ಅಥವಾ ವಿಭಾಗ ಇಲ್ಲ","mr":"इयत्ता किंवा तुकडी दिलेली नाही"},

